import * as C from './core.js';
import * as T from './training.js';
import {MOVEMENTS,CONDITIONING,movement,findMovement,LABELS} from './catalog.js';
import {estimateMax} from './programs.js';
import {openStore,writeStore} from './storage.js';
const $=s=>document.querySelector(s),view=$('#view');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const escape=esc;
const btn=(label,action,data='',cls='')=>`<button data-action="${action}" ${data} class="${cls}">${label}</button>`;
const date=v=>new Date(/^\d{4}-\d{2}-\d{2}$/.test(v)?`${v}T12:00`:v).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const clock=ms=>{const n=Math.max(0,Math.floor(ms/1000));return (n>=3600?Math.floor(n/3600)+':':'')+String(Math.floor(n/60)%60).padStart(2,'0')+':'+String(n%60).padStart(2,'0');};
const heading=(title,sub='')=>`<div class="page-title"><h1>${esc(title)}</h1>${sub?`<p class="muted">${esc(sub)}</p>`:''}</div>`;
const options=(items,current)=>items.map(v=>{const [id,label]=Array.isArray(v)?v:[v,v];return `<option value="${esc(id)}" ${id===current?'selected':''}>${esc(label)}</option>`;}).join('');
let validationError=false;
let state,route='home',queued=Promise.resolve(),pending=0,failedChange=null,workerRegistration=null,channel=null,toastTimeout,dirty=false;
let configDraft=null,selectedDay=null,selectedHistory=null,progressKey='',picker=null,pickerSearch='',editRows=null,editProgramReps=true,backupCandidate=null,testRestDeadline=0;
const openState=new Map();let lastRoute=null;
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').hidden=true,5000);}
function error(text){validationError=true;saveStatus('Entry not saved');$('#save-error').hidden=false;$('#save-error').innerHTML=`<p>${esc(text)}</p>${failedChange?btn('Retry unsaved change','retry'):''}${btn('Dismiss','dismiss-error')}`;}
function saveStatus(text){$('#save-state').textContent=text;}
function commit(action,redraw=true){pending++;saveStatus('Saving…');const task=queued.then(async()=>{if(failedChange){error('Retry the unsaved change before continuing.');return false;}let next;try{next=C.copy(state);action(next);next.revision=state.revision+1;next.updatedAt=C.iso();C.validateState(next);}catch(e){if(redraw)render();error(e.message);return false;}try{await writeStore(next,state.revision);state=next;validationError=false;$('#save-error').hidden=true;channel?.postMessage(state.revision);if(redraw)render();return true;}catch(e){failedChange={action,redraw};error(e.message);return false;}}).finally(()=>{pending--;saveStatus(failedChange?'Unsaved change':validationError?'Entry not saved':pending?'Saving…':dirty?'Setup changes not saved':'Saved on this device');});queued=task;return task;}
function modal(title,body,actions=[]){$('#modal-body').innerHTML=`<h2 id="modal-title">${esc(title)}</h2>${body}<div class="actions gap">${actions.join('')}${btn('Cancel','close-modal')}</div>`;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){$('#modal').close();}
async function go(next){await queued;if(failedChange)return error('Retry your unsaved change first.');if(dirty&&!confirm('Leave without saving setup changes?'))return;dirty=false;configDraft=null;route=next;render();window.scrollTo({top:0});}
const pref=()=>T.profile(state),unit=()=>pref().inputUnit;
function weight(v){if(v===null)return '—';const p=pref();return p.displayUnit==='both'?`${T.displayNumber(v)} lb / ${T.displayNumber(v/T.KG)} kg`:`${T.displayNumber(T.fromLb(v,p.displayUnit))} ${p.displayUnit}`;}
const repsText=n=>`${n??'—'} ${n===1?'rep':'reps'}`;
function result(e,v){if(e.metric==='strength')return `${repsText(v.reps)} · ${weight(v.weight)}`;if(e.metric==='reps')return repsText(v.reps);if(e.metric==='hold')return `${v.seconds??'—'} sec`;return `${v.seconds===null?'Record time':clock(v.seconds*1000)}${v.distance===null?'':` · ${v.distance} ${e.distanceUnit}`}`;}
const icon=path=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${path}</svg>`;
const ICONS={strength:icon('<path d="M3 9v6M6 6v12M18 6v12M21 9v6M6 12h12"/>'),se:icon('<path d="M4 12a8 8 0 0 1 13.7-5.6L20 9M20 4v5h-5M20 12a8 8 0 0 1-13.7 5.6L4 15M4 20v-5h5"/>'),e:icon('<path d="M3 12h4l2.5-6 4 12 2.5-6h5"/>'),hic:icon('<path d="M13 3 5 14h6l-1 7 8-11h-6z"/>'),rest:icon('<path d="M20 15A8.5 8.5 0 0 1 9 4a8.5 8.5 0 1 0 11 11z"/>'),recovery:icon('<path d="M5 19c0-8 5-13 15-14 0 10-5 15-13 15M5 19l7-7"/>')};
const typeIcon=type=>ICONS[type]||ICONS.strength;
const FORMAT={ladder:'Ladder',pyramid:'Pyramid'};
const addedSign=e=>e.reference?.bodyweight?'+':'';
function targetLine(e){const v=e.sets.map(s=>s.target||s),n=v.length,f=v[0];if(e.metric==='strength')return `${n} × ${f.reps??'—'}${f.weight?` · ${addedSign(e)}${weight(f.weight)}`:e.reference?.bodyweight?' · bodyweight':''}`;if(e.metric==='hold')return `${n} × ${f.seconds??'—'} sec`;if(e.metric==='cardio'){const one=f.distance!==null?`${f.distance} ${e.distanceUnit}`:f.seconds!==null?clock(f.seconds*1000):'Record time';return n===1?one:`${n} × ${one}`;}if(v.some(x=>x.reps!==f.reps))return `${FORMAT[e.format]||'Sets'} ${v.map(x=>x.reps??'—').join(' · ')}`;return f.reps===null?`${n} sets · log reps`:`${n} × ${f.reps}`;}
function loadLabel(e){if(e.reference)return `${Math.round(e.reference.percent*100)}% of ${e.reference.factor===.9?'training max':'1RM'}`;if(e.loading&&e.metric==='reps')return `${Math.round(e.loading.percent*100)}% of max reps`;return '';}
const isOpen=(key,fallback)=>openState.has(key)?openState.get(key):fallback;
const panel=(key,title,sub,body,fallback=false)=>`<details class="panel" ${isOpen(key,fallback)?'open':''}><summary data-open="${esc(key)}"><span class="panel-title">${esc(title)}${sub?`<small>${esc(sub)}</small>`:''}</span></summary><div class="panel-body">${body}</div></details>`;
function weekStrip(){const seq=state.plan.sequence,cur=state.plan.cursor,start=Math.floor(cur/7)*7,days=seq.slice(start,start+7);if(!state.plan.program||!days.length)return '';return `<ol class="week-strip" aria-label="This program week">${days.map((id,i)=>{const t=state.templates.find(t=>t.id===id),at=start+i,status=at<cur||state.plan.program.completed?'done':at===cur?'now':'';return `<li class="${status}" aria-label="Day ${i+1}: ${esc(t?.name)}${status==='done'?', done':status==='now'?', next':''}">${typeIcon(t?.guide?.type)}<small>${i+1}</small></li>`;}).join('')}</ol>`;}
function isPlaceholder(t){return /\bQA\b|movement five|core movement/i.test(t.name||t.title||'')||t.exercises.some(e=>/movement five|core movement/i.test(e.name));}
function setupSummary(){const p=state.plan.configuration;if(!p)return '<p class="help">Choose your training plans once in Settings.</p>';return `<div class="plan-summary"><span><small>Barbell</small><strong>${esc(p.barbell)}</strong></span><span><small>Conditioning</small><strong>${state.plan.program?.id==='tb2-standard-2015-v1'?'Base Building → ':''}${esc(p.conditioning)}</strong></span><span><small>Calisthenics</small><strong>${p.calis.length} movements</strong></span></div>`;}
function home(){const t=C.pendingTemplate(state),active=C.activeWorkout(state),configured=!!state.plan.configuration,isDay=x=>['rest','recovery'].includes(x?.guide?.type);
 if(!configured)return heading('Your training')+`<section class="card gap"><h2>Set up your plan</h2><p class="help">Choose barbell training, conditioning and calisthenics. No current maximums are needed to set up or begin Base Building.</p><div class="actions gap">${btn('Choose training plans','settings','','primary wide')}</div></section>${state.workouts.length?'<p class="small gap">Previous records are kept in Progress. The earlier preview contained sample workouts, not your personal program.</p>':''}`;
 const started=!active&&t?state.workouts.find(w=>w.status==='active'&&w.planRef?.version===state.plan.version&&w.planRef.position===state.plan.cursor&&w.planRef.cycle===state.plan.cycle):null,lines=t?t.exercises.filter(e=>e.section!=='calisthenics').map(e=>{const f=e.sets[0],pct=e.reference?` · ${Math.round(e.reference.percent*100)}%`:'';return `<div class="lift-line"><strong>${esc(e.name===t.name?'Target':e.name)}</strong><span>${e.metric==='strength'&&f.weight?`<b>${addedSign(e)}${esc(weight(f.weight))}</b><small>${e.sets.length} × ${f.reps}${pct}</small>`:`<small>${esc(targetLine(e))}</small>`}</span></div>`;}).join(''):'',calis=t?t.exercises.filter(e=>e.section==='calisthenics').map(e=>`${e.name} ${targetLine(e)}`):[];
 return heading('Today',t?.guide?`Week ${t.guide.week} · Day ${t.guide.day}`:'Review your next block')+weekStrip()+
 (C.sinceTraining(state)!==null&&C.sinceTraining(state)>=7?`<section class="notice gap"><h2>Review after a break</h2><p class="help">${C.sinceTraining(state)} days since planned training. Your next session and loads have not been reset.</p>${btn('Review plan','plan','','gap')}</section>`:'')+
 (T.retestMessage(state)?`<section class="notice gap"><h2>Maximum review</h2><p class="help">${esc(T.retestMessage(state))}</p><div class="actions gap">${btn('Review maximums','maxima')}${btn('Choose next block','settings')}</div></section>`:'')+
 (active?`<section class="session gap"><div class="session-head">${typeIcon(active.guide?.type)}<div><span class="eyebrow">In progress</span><h2>${esc(active.title)}</h2></div></div>${isDay(active)?'':`<p class="small">Workout clock <span class="mono" data-clock="${esc(active.id)}">${clock(C.elapsed(active.timer))}</span></p>`}<div class="actions gap">${btn(isDay(active)?'Open day':'Resume workout','resume',`data-id="${esc(active.id)}"`,'primary wide')}</div></section>`:t?`<section class="session gap"><div class="session-head">${typeIcon(t.guide?.type)}<div><span class="eyebrow">${esc(LABELS[t.guide?.type]||t.category)}</span><h2>${esc(t.name)}</h2></div></div>${t.needsMax?`<p class="help gap">${esc(t.exercises.filter(e=>e.needsMax).map(e=>e.name).join(', '))} ${t.exercises.filter(e=>e.needsMax).length===1?'needs a maximum':'need maximums'} before lifting. Your place in the plan stays unchanged.</p>`:isDay(t)?`<p class="help gap">${esc(t.notes)}</p>`:`<div class="lift-lines">${lines}</div>`}${calis.length&&!t.needsMax?`<p class="small gap">Then calisthenics: ${esc(calis.join(' · '))}</p>`:''}${t.guide?.type==='strength'&&T.waveWeek(t)%6===0&&t.exercises.some(e=>e.autoTarget)?'<p class="small gap">Last week of this calisthenics wave. Retest your maxes when it ends.</p>':''}${started?'<p class="small gap">Already started. Your logged sets are kept.</p>':''}<div class="actions gap">${started?btn(isDay(t)?'Open day':'Resume workout','resume',`data-id="${esc(started.id)}"`,'primary wide'):btn(t.needsMax?'Set / test maximums':isDay(t)?'Open day':"Start today's workout",t.needsMax?'maxima':'start',`data-id="${esc(t.id)}"`,'primary wide')}</div></section>`:'<p class="help gap">Block complete. Choose the next phase in Settings; history stays intact.</p>')+
 `<div class="actions gap">${btn('Do something else','other')}${t?btn('Edit upcoming day','edit-day',`data-id="${esc(t.id)}"`):''}</div>`;
}
function checks(name,ids,choices,labels={}){return `<div class="choice-list">${choices.map(m=>`<label class="check"><input type="checkbox" name="${name}" value="${m.id}" ${ids.includes(m.id)?'checked':''}>${esc(labels[m.id]||m.name)}</label>`).join('')}</div>`;}
function settings(){const p=configDraft||pref(),u=pref(),maxes=[...new Set(state.maxTests.map(t=>t.name))].slice(0,3).map(n=>{const m=T.latestMax(state,n);return `${n} ${maxText(m.metric,m.maximum)}`;}).join(' · ');const first=!state.plan.configuration;return heading('Settings')+`<form id="config-form" class="stack gap">`+panel('set:plans','Training plans',`${p.barbell} · ${p.conditioning}${p.baseFirst?' · Base Building first':''}`,`<label>Barbell plan<select name="barbell">${options(['Operator','Fighter','Zulu'],p.barbell)}</select></label><p class="small">Operator: 3 strength days. Fighter: 2. Zulu: 4 shorter A/B sessions.</p><label class="gap">Conditioning plan<select name="conditioning">${options([['Black','Black · strength + high-intensity conditioning'],['Green','Green · endurance focus (Fighter)']],p.conditioning)}</select></label><label class="check gap"><input type="checkbox" name="baseFirst" ${p.baseFirst?'checked':''}>Start with the eight-week Base Building opener</label><details class="gap"><summary>Main lifts</summary>${checks('cluster',p.cluster,MOVEMENTS.filter(m=>['Barbell','Main lift'].includes(m.group)||m.id==='pullups'||p.cluster.includes(m.id)),{pullups:'Bodyweight pullups'})}<p class="small">Operator: 2–3 main lifts. Zulu: 4, split A/B. Each lift needs its own maximum. The book says to use bodyweight pullups until you reach 10 strict reps, then move to weighted.</p></details><details><summary>Strength-endurance circuit</summary><p class="help">Choose 5–8 light, rep-based exercises.</p>${checks('circuit',p.circuit,MOVEMENTS.filter(m=>m.metric==='reps'||m.metric==='strength'))}</details><div class="field-grid gap"><label>Easy endurance<select name="endurance">${options(CONDITIONING.filter(c=>c.type==='e').map(c=>[c.id,c.name]),p.endurance)}</select></label><label>High-intensity workout<select name="hic">${options(CONDITIONING.filter(c=>c.type==='hic').map(c=>[c.id,c.name]),p.hic)}</select></label><label>Workout version<select name="variant">${options(Object.keys(CONDITIONING.find(c=>c.id===p.hic)?.variants||{}),p.variant)}</select></label></div>`,first)+panel('set:calis','Calisthenics',`${p.calis.length} ${p.calis.length===1?'movement':'movements'} · ${({ladder:'Ladder',pyramid:'Pyramid',sets:'Sets','near-failure':'Near-failure'})[p.calisFormat]} · ${p.calisRest} s rest`,`<p class="help">Follows strength days. It isn't added to Base Building circuits.</p>${checks('calis',p.calis,MOVEMENTS.filter(m=>['Calisthenics','Rings','Core'].includes(m.group)))}<div class="field-grid gap"><label>Format<select name="calisFormat">${options([['ladder','Ladder'],['pyramid','Pyramid'],['sets','Sets'],['near-failure','Near-failure sets']],p.calisFormat)}</select></label><label>Reps per set / rung<input name="calisReps" value="${esc(p.calisReps.map(v=>v??'').join(', '))}" placeholder="For example: 1, 2, 3"></label><label>Hold · seconds<input name="calisHold" type="number" min="1" max="3600" value="${p.calisHold}"></label><label>Rest · seconds<input name="calisRest" type="number" min="0" max="3600" value="${p.calisRest}"></label></div>${p.calis.some(id=>p.cluster.includes(id))?'<p class="small gap">Some movements are also main lifts, so review the combined volume.</p>':''}<p class="small gap">A movement with a max in Maximums gets its targets from that max. Without one, it uses these reps. Near-failure sets always use these reps; leave them blank and log what you do.</p>${state.plan.configuration?btn('Update calisthenics for remaining strength days','save-calis','','gap'):''}`)+`${btn('Preview training plan','preview-config','','primary wide')}</form><div class="stack gap">`+panel('set:units','Units and rest',`${u.displayUnit==='both'?'lb and kg':u.displayUnit} · ${u.increment} ${u.incrementUnit} plates · ${clock((u.liftRest??120)*1000)} lift rest`,`<form id="units-form" class="field-grid"><label>Show weights<select name="displayUnit">${options([['lb','Pounds (lb)'],['kg','Kilograms (kg)'],['both','Both lb and kg']],u.displayUnit)}</select></label><label>Enter weights in<select name="inputUnit">${options(['lb','kg'],u.inputUnit)}</select></label><label>Plate increment · total bar<input name="increment" type="number" min="0.5" max="100" step="0.5" value="${u.increment}"></label><label>Increment unit<select name="incrementUnit">${options(['lb','kg'],u.incrementUnit)}</select></label><label>Training reference<select name="factor">${options([['0.9','90% training max'],['1','Full 1RM']],String(u.factor))}</select></label><label>Rest between lift sets · seconds<input name="liftRest" type="number" inputmode="numeric" min="0" max="3600" step="1" required value="${u.liftRest??120}"></label>${btn('Save units and rest','save-units','','primary full')}</form><p class="small gap">The book's minimum between main lift sets is 2 minutes. A different rest time starts a separate Progress graph for that lift. You can still change any rest during a workout.</p>`)+`<button class="panel-link" data-action="maxima"><span class="panel-title">Maximums and testing<small>${esc(maxes||'None set yet')}</small></span></button>`+backupSettings()+'</div>';}
function backupSettings(){return panel('set:backup','Backup',`Last export: ${state.settings.lastExportAt?date(state.settings.lastExportAt):'Not yet'}`,`<p class="help">Export a file and save it to Google Drive. There is no account connection or automatic sync.</p><div class="actions gap">${btn('Export backup file','export','','primary')}${btn('Share backup','share')}</div><label class="gap">Restore backup<input id="backup-input" type="file" accept=".json,application/json"></label><p class="small">Restoring replaces this device’s data after confirmation. Export first to keep the current copy.</p><details class="gap"><summary>Offline storage</summary><p class="help">Open online once to cache the app. Keep a backup before moving to another phone or address.</p>${btn('Request persistent storage','persistent')}</details>`);}
function readConfig(){const d=new FormData($('#config-form')),p=configDraft||pref();return {...p,barbell:d.get('barbell'),conditioning:d.get('conditioning'),baseFirst:d.has('baseFirst'),cluster:d.getAll('cluster'),circuit:d.getAll('circuit'),calis:d.getAll('calis'),endurance:d.get('endurance'),hic:d.get('hic'),variant:d.get('variant'),calisFormat:d.get('calisFormat'),calisReps:String(d.get('calisReps')).trim()===''?[null,null,null]:String(d.get('calisReps')).split(',').map(v=>v.trim()===''?null:Number(v)),calisHold:Number(d.get('calisHold')),calisRest:Number(d.get('calisRest'))};}
function plan(){const ids=state.plan.sequence,p=state.plan.configuration;return heading('Plan')+setupSummary()+`<div class="actions gap">${btn('Configure plans','settings')}</div>${p?`<details class="gap"><summary>Review after a break</summary><p class="help">Resume, review maximums, or repeat from a program week. Recorded history stays.</p><label class="gap">Repeat from week<select id="repeat-week">${options(Array.from({length:Math.ceil(ids.length/7)},(_,i)=>[String(i+1),String(i+1)]),String(Math.floor(state.plan.cursor/7)+1))}</select></label>${btn('Preview repeat week','repeat-week','','gap')}</details>`:''}`+(!p?'<p class="help gap">Existing preview/personal routines are retained. Use Settings to create your coordinated plan.</p>':`<p class="small gap">Days advance when you log them, not when a weekday passes.</p>`)+Array.from({length:Math.ceil(ids.length/7)},(_,wi)=>`<details class="panel gap" ${wi===Math.floor(state.plan.cursor/7)?'open':''}><summary><span class="panel-title">Week ${wi+1}</span></summary><div class="plan-days">${ids.slice(wi*7,wi*7+7).map((id,j)=>{const t=state.templates.find(t=>t.id===id),index=wi*7+j,next=index===state.plan.cursor&&!state.plan.program?.completed,done=index<state.plan.cursor;return `<button class="plan-day ${next?'now':done?'done':''}" data-action="edit-day" data-id="${esc(t.id)}">${typeIcon(t.guide?.type)}<span><small>Day ${j+1}${next?' · Next':done?' · Done':''}${t.custom?' · changed':''}${t.needsMax?' · maximums needed':''}</small><strong>${esc(t.name)}</strong></span></button>`;}).join('')}</div></details>`).join('');}
function dayEditor(){const t=state.templates.find(t=>t.id===selectedDay);if(!t)return heading('Day unavailable');const locked=state.workouts.some(w=>w.templateId===t.id&&(w.status==='active'||w.completion==='full'));
 if(!editRows)editRows=t.exercises.filter(e=>!['calisthenics','conditioning'].includes(e.section)).map(e=>({id:e.catalogId||MOVEMENTS.find(m=>m.name===e.name)?.id||'',sets:e.sets.length,reps:e.sets[0].reps,seconds:e.sets[0].seconds,weight:e.metric==='strength'?T.fromLb(e.sets[0].weight||0,unit()):0}));
 return btn('← Plan','plan','','back')+heading(t.name,`${LABELS[t.guide?.type]||t.category}${t.guide?` · Week ${t.guide.week}, day ${t.guide.day}`:''}`)+`<details class="gap" open><summary>Workout instructions</summary><p class="help">${esc(t.notes)}</p></details>`+(locked?'<p class="help gap">This day already has results or an unfinished workout. Its snapshot is kept intact; choose an unstarted day to change the future plan.</p>': ['e','hic'].includes(t.guide?.type)?`<form id="condition-form" class="card gap"><h2>Change workout</h2><label>Book session<select name="choice">${options(CONDITIONING.filter(c=>c.type===t.guide.type).map(c=>[c.id,`${c.name} · ${c.book}`]),t.exercises[0].catalogId)}</select></label>${t.guide.type==='hic'?`<label class="gap">Version<select name="variant">${options(Object.keys(CONDITIONING.find(c=>c.id===t.exercises[0].catalogId)?.variants||{basic:{}}),'basic')}</select></label>`:''}<label class="gap">Apply to<select name="scope">${options([['day','This day only'],['block','Matching days in the remaining block']],'day')}</select></label>${btn('Preview change','preview-condition','','primary gap')}</form>`:['rest','recovery'].includes(t.guide?.type)?'<p class="help gap">This is a recovery/rest position. Use Do something else on Workout to log another activity without pretending it was rest.</p>':`<form id="day-form" class="stack gap"><p class="help">Choose movements by name. Changed movements need their own maximum; future TB percentages stay in place.</p>${editRows.map((r,i)=>`<section class="card"><label>Exercise ${i+1}<select data-edit-row="${i}" data-edit-field="id">${options([['','Choose a named movement'],...MOVEMENTS.filter(m=>['strength','reps'].includes(m.metric)).map(m=>[m.id,m.name])],r.id)}</select></label><div class="field-grid gap"><label>Sets / rounds<input type="number" min="1" max="30" data-edit-row="${i}" data-edit-field="sets" value="${r.sets}"></label><label>Reps<input type="number" min="0" max="10000" data-edit-row="${i}" data-edit-field="reps" value="${r.reps??''}"></label>${findMovement(r.id)?.metric==='strength'&&t.guide?.type==='se'?`<label>Light load · ${unit()}<input type="number" min="0" step="any" data-edit-row="${i}" data-edit-field="weight" value="${r.weight||0}"></label>`:''}</div>${btn('Remove exercise','remove-edit',`data-index="${i}"`,'gap')}</section>`).join('')}<div class="actions">${btn('Add movement','add-edit')}</div><label class="check"><input id="keep-program" type="checkbox" ${editProgramReps?'checked':''}>Keep each future day’s program sets and reps</label><p class="small">Uncheck to use your entered sets/reps across the selected days. Percentage-based loads are recalculated for each future week.</p><label class="check"><input id="save-routine" type="checkbox">Also save these movements for future blocks</label><label>Apply to<select id="edit-scope">${options([['day','This day only'],['block','Matching days in the remaining block']],'block')}</select></label>${btn('Preview changes','preview-edit','','primary wide')}</form>`)+(['rest','recovery'].includes(t.guide?.type)?'':`<details class="gap"><summary>Original targets</summary>${t.exercises.map(e=>`<p>${esc(e.name)} · ${e.sets.length} sets · ${esc(result(e,e.sets[0]))}</p>`).join('')}</details>`);
}
function heads(e){if(e.metric==='strength')return ['Reps',`${addedSign(e)}${unit()}`];if(e.metric==='reps')return ['Reps'];if(e.metric==='hold')return ['Sec'];return e.timeUnit==='seconds'?['Min','Sec',e.distanceUnit]:['Min',e.distanceUnit];}
