function setRow(w,e,ei,si,lead,next,readonly,named=false){const s=e.sets[si],data=`data-workout="${esc(w.id)}" data-exercise="${ei}" data-set="${si}"`,note=differs(s)?`<small class="set-note">Target ${esc(result(e,s.target))}</small>`:'',both=pref().displayUnit==='both'&&e.metric==='strength';if(readonly||e.omitted)return `<div class="set-row flat ${named?'named':''}"><span class="set-no">${lead}</span><span>${esc(result(e,s.actual))}${s.done?'':' · not logged'}</span><span class="${s.done?'tick':'small'}">${s.done?'✓':'—'}</span>${note}</div>`;return `<div class="set-row ${named?'named':''} ${s.done?'is-done':next?'is-next':''}" style="--cols:${heads(e).length}"><span class="set-no">${lead}</span>${fields(e,s.actual,data)}<label class="done"><input type="checkbox" data-field="done" ${data} ${s.done?'checked':''} aria-label="${esc(e.name)} set ${si+1} done"><span>✓</span></label>${both?`<small class="set-note" data-weight-equivalent ${data}>${esc(weight(s.actual.weight))}</small>`:''}${note}</div>`;}
